set local search_path=public,extensions;
select pg_temp.check(not exists(select 1 from public.rooms r join s4_upgrade_rooms old using(id) where (to_jsonb(r)-array['meeting_starts_at','meeting_ends_at','meeting_time_zone','s4_revision','appointment_confirmed_at','appointment_confirmed_by'])<>old.v),'upgrade preserves every existing room field exactly');
select pg_temp.check(not exists(select 1 from public.rooms where meeting_starts_at is not null or meeting_ends_at is not null or meeting_time_zone is not null or appointment_confirmed_at is not null or appointment_confirmed_by is not null or s4_revision<>0),'zero structured-time or owner-evidence backfill');
select pg_temp.check(not exists(select 1 from public.participants p join s4_upgrade_members old using(id) where to_jsonb(p)<>old.v),'upgrade preserves every legacy schedule and vote');
select pg_temp.check(not exists(select 1 from public.dutch_pay_bills b join s4_upgrade_bills old using(id) where to_jsonb(b)<>old.v),'upgrade preserves settlement accounts expiry and close state');
select pg_temp.check(not has_function_privilege('authenticated','public.update_settlement_amount(uuid,integer)','EXECUTE') and not has_function_privilege('anon','public.update_settlement_amount(uuid,integer)','EXECUTE') and not exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.oid='public.update_settlement_amount(uuid,integer)'::regprocedure and a.grantee=0 and a.privilege_type='EXECUTE'),'upgrade closes the retired amount RPC for all client principals');
select pg_temp.check(not exists(select 1 from public.room_invitations i join public.rooms r on r.id=i.room_id where r.stage in('settling','done') and i.status='pending'),'upgrade expires all historical settlement-stage pending invitations');
select pg_temp.check((select to_jsonb(i)=(select value from s4_upgrade_invitations where id=i.id) from public.room_invitations i where id='97000000-0000-4000-8000-000000000072'),'upgrade preserves accepted invitation exactly');
select pg_temp.check((select to_jsonb(i)=(select value from s4_upgrade_invitations where id=i.id) from public.room_invitations i where id='97000000-0000-4000-8000-000000000021'),'upgrade preserves place pending invitation exactly');
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(pg_temp.sqlstate_of(format('select public.update_settlement_amount(%L,999999)',bill))='42501','upgraded preconfirmation legacy bill cannot use retired RPC: '||bill) from (values('99000000-0000-4000-8000-000000000001'),('99000000-0000-4000-8000-000000000002')) legacy(bill);
select pg_temp.check(public.get_s4_capabilities()->>'atomic_confirmation'='true','capability is active only after M3');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000001')->>'time_status'='legacy_unverified','ambiguous label is legacy unverified');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000002')->>'restaurant' is null,'location name alone never becomes a restaurant');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000003')->>'confirmation_status'='legacy_partial','partial restaurant evidence remains partial');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000004')->'restaurant'->'item_id'='null'::jsonb,'legacy label without ID is never inferred into a candidate');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000005')->>'confirmation_status'='legacy_confirmed','historical completion does not become owner confirmation');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000006')->>'stage'='settling' and public.get_room_s4_state('26000000-0000-4000-8000-000000000007')->>'stage'='done','historical settling and done stages are preserved');
select pg_temp.check(public.create_room_settlement_v2('26000000-0000-4000-8000-000000000006','Legacy active bill',2000,'Synthetic','0000','A')=(select id from s4_upgrade_bill),'historical unverified active settlement retains the existing retry path');
select pg_temp.check(pg_temp.sqlstate_of(format('select public.%I(%L,%L,2000,%L,%L,%L)',rpc,room_id,'Changed legacy','Synthetic','1111','A'))='S4008','upgraded unconfirmed open bill stays guarded: '||rpc||' '||room_id)
from (values('26000000-0000-4000-8000-000000000001'),('26000000-0000-4000-8000-000000000002')) rooms(room_id)
cross join (values('create_room_settlement_v2'),('create_room_settlement')) names(rpc);
select pg_temp.check(pg_temp.sqlstate_of($q$select public.create_room_settlement_v2('26000000-0000-4000-8000-000000000007','New legacy done bill',2000,'Synthetic','0000','A')$q$)='S4008','upgraded done room without owner evidence cannot start a new bill');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000001')->'availability'->>'submitted_count'='1','legacy invalid date is ignored while valid future cell is retained');
select pg_temp.check(public.add_voting_item('26000000-0000-4000-8000-000000000003','menu','Reselected restaurant') is not null,'legacy partial is_confirmed does not freeze candidates');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.toggle_vote('26000000-0000-4000-8000-000000000007','96000000-0000-4000-8000-000000000001')$q$)='S4003','legacy done never reopens voting');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.advance_room_stage('26000000-0000-4000-8000-000000000003','confirmed')$q$)='S4007','legacy partial requires explicit structured time before recovery');
select public.select_room_meeting_time_v1('26000000-0000-4000-8000-000000000003',jsonb_build_object('starts_at',((clock_timestamp() at time zone 'Asia/Seoul')::date+1)::text||'T11:00:00+09:00','ends_at',((clock_timestamp() at time zone 'Asia/Seoul')::date+1)::text||'T12:00:00+09:00','time_zone','Asia/Seoul'),(select s4_revision from public.rooms where id='26000000-0000-4000-8000-000000000003'),gen_random_uuid());
select pg_temp.check(public.advance_room_stage('26000000-0000-4000-8000-000000000003','confirmed')='confirmed','legacy valid candidate recovers through atomic confirmation core');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000003')->>'confirmation_status'='owner_confirmed','only explicit recovery writes new owner evidence');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000008')->'permissions'->>'can_submit'='true','legacy place 8 permits schedule recovery');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.select_room_meeting_time_v1('26000000-0000-4000-8000-000000000008',jsonb_build_object('starts_at',((clock_timestamp() at time zone 'Asia/Seoul')::date+1)::text||'T11:00:00+09:00','ends_at',((clock_timestamp() at time zone 'Asia/Seoul')::date+1)::text||'T12:00:00+09:00','time_zone','Asia/Seoul'),(select s4_revision from public.rooms where id='26000000-0000-4000-8000-000000000008'),gen_random_uuid())$q$)='S4006','legacy place 8 cannot select before a usable schedule');
select public.submit_room_availability_v1('26000000-0000-4000-8000-000000000008',array[to_char((clock_timestamp() at time zone 'Asia/Seoul')::date+1,'YYYY-MM-DD')||'-11'],(select s4_revision from public.rooms where id='26000000-0000-4000-8000-000000000008'),gen_random_uuid());
select public.select_room_meeting_time_v1('26000000-0000-4000-8000-000000000008',jsonb_build_object('starts_at',((clock_timestamp() at time zone 'Asia/Seoul')::date+1)::text||'T11:00:00+09:00','ends_at',((clock_timestamp() at time zone 'Asia/Seoul')::date+1)::text||'T12:00:00+09:00','time_zone','Asia/Seoul'),(select s4_revision from public.rooms where id='26000000-0000-4000-8000-000000000008'),gen_random_uuid());
select public.confirm_room_vote('26000000-0000-4000-8000-000000000008','96000000-0000-4000-8000-000000000001');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000008')->>'confirmation_status'='owner_confirmed','legacy place 8 recovers all the way to owner confirmation');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000009')->'permissions'->>'can_submit'='true','legacy place 9 permits schedule recovery');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.select_room_meeting_time_v1('26000000-0000-4000-8000-000000000009',jsonb_build_object('starts_at',((clock_timestamp() at time zone 'Asia/Seoul')::date+1)::text||'T11:00:00+09:00','ends_at',((clock_timestamp() at time zone 'Asia/Seoul')::date+1)::text||'T12:00:00+09:00','time_zone','Asia/Seoul'),(select s4_revision from public.rooms where id='26000000-0000-4000-8000-000000000009'),gen_random_uuid())$q$)='S4006','legacy place 9 cannot select before a usable schedule');
select public.set_my_availability('26000000-0000-4000-8000-000000000009',array[to_char((clock_timestamp() at time zone 'Asia/Seoul')::date+1,'YYYY-MM-DD')||'-11']);
select public.select_room_meeting_time_v1('26000000-0000-4000-8000-000000000009',jsonb_build_object('starts_at',((clock_timestamp() at time zone 'Asia/Seoul')::date+1)::text||'T11:00:00+09:00','ends_at',((clock_timestamp() at time zone 'Asia/Seoul')::date+1)::text||'T12:00:00+09:00','time_zone','Asia/Seoul'),(select s4_revision from public.rooms where id='26000000-0000-4000-8000-000000000009'),gen_random_uuid());
select public.confirm_room_vote('26000000-0000-4000-8000-000000000009','96000000-0000-4000-8000-000000000001');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000009')->>'confirmation_status'='owner_confirmed','legacy place 9 recovers all the way to owner confirmation');
select pg_temp.check(public.get_room_s4_state('26000000-0000-4000-8000-000000000006')->>'confirmation_status'='legacy_settlement_unverified' and public.get_room_s4_state('26000000-0000-4000-8000-000000000007')->>'confirmation_status'='legacy_settlement_unverified','historical settlement stages never imply verified appointment confirmation');
reset role;
select pg_temp.check((select count(*)=3 from public.messages where event_key like 'appointment-confirmed:26000000-%'),'upgrade emits no retrospective events and each explicit recovery emits one');
